    "source": "architecture \"Customer platform\" {\n  description \"A connected experience, from first visit to fulfilled order.\"\n\n  model {\n    person customer \"Customer\" {\n      description \"Discovers, orders, and returns.\"\n    }\n    package experience \"Experience layer\" {\n      application storefront \"Storefront\" {\n        description \"One place to discover and shop.\"\n        technology \"Next.js · Web\"\n      }\n      service gateway \"API gateway\" {\n        description \"A secure front door to the platform.\"\n        technology \"REST · OAuth 2.0\"\n        icon core.shield\n      }\n    }\n    package commerce \"Commerce core\" {\n      service orders \"Order service\" {\n        description \"Owns the order lifecycle.\"\n        technology \"Node.js · Events\"\n      }\n      database data \"Order database\" {\n        description \"The source of truth for orders.\"\n        technology \"PostgreSQL\"\n      }\n    }\n    system payment \"Payment provider\" {\n      description \"External payment processing.\"\n      technology \"Partner API\"\n      icon core.globe\n    }\n    relation browse customer -> storefront \"Browses & orders\"\n    relation request storefront -> gateway \"HTTPS\"\n    relation create gateway -> orders \"Creates order\"\n    relation persist orders -> data \"Reads / writes\" { type access }\n    relation charge orders -> payment \"Authorizes payment\" { type dependency }\n  }\n\n  view landscape \"Platform landscape\" {\n    direction right\n    spacing 90\n    place customer at (0, 182)\n    place experience at (330, 0)\n    place commerce at (1000, 0)\n    place payment at (1028, 360)\n    style storefront { accent \"#6366f1\" }\n    style orders { accent \"#0d9488\" }\n    route browse { from right; to left; curve rounded }\n    route create { from right; to left; curve rounded }\n    route charge { from bottom; to top; curve rounded }\n  }\n\n  view journey \"Customer journey\" {\n    include customer, storefront, gateway\n    direction right\n    spacing 100\n    route browse { curve bezier }\n    route request { curve rounded }\n  }\n\n  view services \"Commerce detail\" {\n    include commerce, payment\n    direction down\n    spacing 90\n    style orders { template component; accent \"#8b5cf6\" }\n    route persist { curve rounded }\n    route charge { curve bezier }\n  }\n}\n"
