    "source": "architecture \"Event-driven checkout\" {\n  description \"Precise composition with ports, waypoints, and a custom feedback path.\"\n  model {\n    application checkout \"Checkout\" {\n      description \"Captures a customer's intent.\"\n      technology \"Web application\"\n    }\n    service orders \"Order service\" {\n      description \"Validates and confirms orders.\"\n      technology \"Node.js\"\n    }\n    queue events \"Order events\" {\n      description \"Decouples producers and consumers.\"\n      technology \"Kafka\"\n    }\n    service fulfilment \"Fulfilment\" {\n      description \"Picks, packs, and dispatches.\"\n    }\n    database store \"Order store\" {\n      description \"Durable order history.\"\n      technology \"PostgreSQL\"\n    }\n    relation submit checkout -> orders \"Submit order\"\n    relation publish orders -> events \"Publish\"\n    relation consume events -> fulfilment \"Subscribe\" { type dependency }\n    relation write orders -> store \"Persist\" { type access }\n    relation feedback fulfilment -> checkout \"Delivery updates\"\n  }\n  view precise \"Designed flow\" {\n    place checkout at (0, 0)\n    place orders at (340, 0)\n    place events at (680, 0)\n    place fulfilment at (1020, 0)\n    place store at (340, 300) size (240, 180)\n    route submit { from right; to left; curve straight }\n    route publish { from right; to left; curve rounded }\n    route consume { from right; to left; curve straight }\n    route write { from bottom; to top; via (450, 245), (460, 245); curve rounded; label (485, 245) }\n    route feedback {\n      path \"M 1130 0 C 1130 -130 110 -130 110 0\"\n      label (620, -94)\n    }\n  }\n}\n"
