    "source": "# NAFv4.1 p.118: two service lifelines and two objectified messages.\narchitecture \"NAFv4.1 · S6 Positioned lifelines\" {\n  config {profile naf41-uaf}\n  model {\n    Service service_coordinationService \"Coordination Service\"\n    Service service_sarService \"SAR Service\"\n    ServiceInterface serviceInterface_coordinationInterface \"Coordination Interface\"\n    ServiceInterface serviceInterface_rescueInterface \"Rescue Interface\"\n    ServiceOperation serviceOperation_s3operation \"S3 Operation\"\n    ServiceOperation serviceOperation_s2operation \"S2 operation\"\n    ServiceLifeline serviceLifeline_coordinationServiceLifeline \"Coordination Service Lifeline\"\n    ServiceLifeline serviceLifeline_sarServiceLifeline \"SAR Service Lifeline\"\n    ServiceInteraction serviceInteraction_requestSortie \"Request Sortie\"\n    ServiceInteraction serviceInteraction_acknowledge \"Acknowledge\"\n    relation coordinationTimeline serviceLifeline_coordinationServiceLifeline -> service_coordinationService \"represents a timeline of\" {type RepresentsService}\n    relation sarTimeline serviceLifeline_sarServiceLifeline -> service_sarService \"represents a timeline of\" {type RepresentsService}\n    relation coordinationApi service_coordinationService -> serviceInterface_coordinationInterface \"specifies\" {type SpecifiesServiceInterface}\n    relation rescueApi service_sarService -> serviceInterface_rescueInterface \"specifies\" {type SpecifiesServiceInterface}\n    relation coordinationOperation serviceInterface_coordinationInterface -> serviceOperation_s3operation \"specifies\" {type SpecifiesServiceOperation}\n    relation rescueOperation serviceInterface_rescueInterface -> serviceOperation_s2operation \"specifies\" {type SpecifiesServiceOperation}\n    relation s6.7 serviceLifeline_coordinationServiceLifeline -> serviceLifeline_sarServiceLifeline \"Request Sortie\" {type ServiceInteraction order 1 interaction serviceInteraction_requestSortie}\n    relation s6.8 serviceLifeline_sarServiceLifeline -> serviceLifeline_coordinationServiceLifeline \"Acknowledge\" {type ServiceInteraction order 2 interaction serviceInteraction_acknowledge}\n    relation requestedOperation serviceInteraction_requestSortie -> serviceOperation_s3operation \"relates to\" {type InteractionRelatesOperation}\n  }\n  view s6 \"S6\" {\n    include service_coordinationService,service_sarService,serviceInterface_coordinationInterface,serviceInterface_rescueInterface,serviceOperation_s3operation,serviceOperation_s2operation,serviceInteraction_requestSortie,serviceInteraction_acknowledge,serviceLifeline_coordinationServiceLifeline,serviceLifeline_sarServiceLifeline\n    viewpoint S6\n    place serviceInterface_coordinationInterface at (1.5*service_coordinationService.width,0)\n    place service_coordinationService at (0,1.5*serviceInterface_coordinationInterface.height)\n    place serviceOperation_s3operation at (1.5*service_coordinationService.width,1.5*serviceInterface_coordinationInterface.height)\n    place service_sarService at (serviceOperation_s3operation.x+1.5*serviceOperation_s3operation.width,1.5*serviceInterface_coordinationInterface.height)\n    place serviceOperation_s2operation at (service_sarService.x+1.5*service_sarService.width,1.5*serviceInterface_coordinationInterface.height)\n    place serviceInterface_rescueInterface at (serviceOperation_s2operation.x,0)\n    place serviceInteraction_requestSortie at (serviceOperation_s3operation.x,serviceOperation_s3operation.y+1.5*serviceOperation_s3operation.height)\n    place serviceLifeline_coordinationServiceLifeline at (service_coordinationService.x,serviceInteraction_requestSortie.y)\n    place serviceLifeline_sarServiceLifeline at (service_sarService.x,serviceInteraction_requestSortie.y)\n    place serviceInteraction_acknowledge at (serviceInteraction_requestSortie.x,serviceInteraction_requestSortie.y+4*serviceInteraction_requestSortie.height)\n    style serviceLifeline_coordinationServiceLifeline { height 5*serviceInteraction_requestSortie.height }\n    style serviceLifeline_sarServiceLifeline { height 5*serviceInteraction_requestSortie.height }\n    route s6.7 { from right 0.4 to left 0.4 }\n    route s6.8 { from left 0.6 to right 0.6 curve straight }\n  }\n}\n"
