    "title": "NAFv4.1 · Search & Rescue",
    "subtitle": "Criteria, needlines & typed flows",
    "source": "architecture \"Search & Rescue · NAFv4.1\" {\n  description \"A typed operational model with measurable capability criteria, service support and physical realization.\"\n  config { profile naf41-uaf }\n  model {\n    Capability rescue \"Search and rescue\"\n    Capability maritime \"Maritime rescue\"\n    relation specializes maritime -> rescue \"Specializes\" { type CapabilityGeneralization }\n\n    AssessmentCriterion response \"Time to dispatch\" {\n      expression \"Dispatch a rescue asset within ten minutes after a validated alert.\"\n    }\n    Measure minutes \"Elapsed dispatch time\" { unit \"minutes\" value 8 }\n    relation criterion response -> maritime \"Characterizes\" { type CharacterizesCapability }\n    relation evaluation minutes -> response \"Evaluates\" { type EvaluatesCriterion }\n\n    OperationalArchitecture commandNode \"Coordination node\"\n    LogicalNode rescueNode \"Rescue team node\"\n    Needline coordinationNeed \"Rescue coordination need\" {\n      source commandNode\n      target rescueNode\n      conveyed [distress]\n    }\n    OperationalPerformer command \"Rescue coordination centre\"\n    OperationalPerformer crew \"Rescue team\"\n    InformationElement distress \"Distress report\"\n    relation groupsCommand commandNode -> command \"Groups active resource\" { type GroupsLogicalResource }\n    relation groupsCrew rescueNode -> crew \"Groups active resource\" { type GroupsLogicalResource }\n    relation alert command -> crew \"Validated alert\" {\n      type LogicalInteraction\n      conveyed [distress]\n      needline coordinationNeed\n    }\n\n    OperationalActivity assess \"Assess distress report\"\n    OperationalActivity dispatch \"Dispatch rescue team\"\n    relation assignment1 command -> assess \"Can perform\" { type IsCapableToPerform }\n    relation assignment2 command -> dispatch \"Can perform\" { type IsCapableToPerform }\n    relation nextStep assess -> dispatch \"Validated distress\" { type LogicalControlFlow }\n    relation capabilityTrace dispatch -> maritime \"Supports\" { type MapsToCapability }\n\n    ServiceSpecification coordinationService \"Rescue coordination service\"\n    ServiceFunction coordinate \"Coordinate rescue assets\"\n    relation supports coordinationService -> maritime \"Contributes\" { type Exhibits }\n    relation serviceFunction coordinationService -> coordinate \"Enables\" { type IsCapableToPerform }\n\n    Software platform \"Rescue coordination platform\" {\n      isStandardConfiguration false\n      technology \"Mission network\"\n    }\n    Function validateReport \"Validate report\"\n    Function transmitDispatch \"Transmit dispatch\"\n    DataEntity reportData \"Dispatch data\"\n    relation assignment3 platform -> validateReport \"Can perform\" { type IsCapableToPerform }\n    relation assignment4 platform -> transmitDispatch \"Can perform\" { type IsCapableToPerform }\n    relation input validateReport -> reportData \"Uses\" { type UsesPhysicalResource }\n    relation output transmitDispatch -> reportData \"Delivers\" { type DeliversPhysicalResource }\n    relation functionFlow validateReport -> transmitDispatch \"Validated report\" { type FunctionalFlow }\n    relation dataFlow validateReport -> transmitDispatch \"Dispatch payload\" {\n      type ResourceFlow\n      conveyed [reportData]\n    }\n    relation realization1 validateReport -> assess \"Implements\" { type Implements }\n    relation realization2 transmitDispatch -> dispatch \"Implements\" { type Implements }\n    relation realization3 transmitDispatch -> coordinate \"Implements service function\" { type Implements }\n\n    CapabilityMilestone firstRelease \"Initial readiness · January 2027\" { date \"2027-01-15\" }\n    CapabilityIncrement initial \"Initial rescue capability\"\n    relation readiness firstRelease -> initial \"Defines increment\" { type DefinesIncrement }\n    relation capabilityDelivery initial -> maritime \"Delivers\" { type DeliversCapability }\n  }\n\n  view criteria \"C7 · Measurable performance\" {\n    viewpoint C7\n    include maritime, response, minutes\n    direction right\n  }\n  view taxonomy \"C1 · Capability taxonomy\" {\n    viewpoint C1\n    include rescue, maritime\n  }\n  view structure \"L2 · Nodes and needline details\" {\n    viewpoint L2\n    include commandNode, rescueNode, coordinationNeed, distress\n    diagram class { propertyFields [source, target, conveyed] }\n  }\n  view interactions \"L3 · Logical interactions\" {\n    viewpoint L3\n    include command, crew, distress\n    direction right\n  }\n  view activities \"L4 · Logical activities\" {\n    viewpoint L4\n    include command, assess, dispatch\n  }\n  view functions \"S4 · Service functions\" {\n    viewpoint S4\n    include coordinationService, coordinate\n  }\n  view physical \"P4 · Resource functions and flows\" {\n    viewpoint P4\n    include platform, validateReport, transmitDispatch, reportData\n    place platform at (250, 0)\n    place validateReport at (0, 230)\n    place transmitDispatch at (500, 230)\n    place reportData at (250, 460)\n    route assignment3 { from left to top curve rounded }\n    route assignment4 { from right to top curve rounded }\n    route input { from bottom to left curve rounded }\n    route output { from bottom to right curve rounded }\n    route functionFlow { from right to left curve rounded }\n    route dataFlow { from bottom to bottom via (110, 430), (610, 430) curve rounded label (360, 430) }\n  }\n  view trace \"L4-P4 · Activity implementation\" {\n    viewpoint L4-P4\n    include assess, dispatch, validateReport, transmitDispatch, coordinate\n  }\n  view roadmap \"Cr · Capability roadmap\" {\n    viewpoint Cr\n    include firstRelease, initial, maritime\n    direction right\n  }\n}\n"
